INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Israel strike 4 countries in 2026?', 'This market will resolve according to the total number of different countries'' soil that Israel initiates a drone, missile, or air strike between January 1, 2026, 12:00 AM ET and December 31, 2026, 11:59 PM ET. Strikes on embassies or consulates will count towards the country the embassy or consulate is located in, not towards the country they represent. Strikes within the territory controlled by Israel as of December 31, 2025, 11:59 PM ET, as well as strikes within the West Bank or the Gaza St', 'politics', 'active', 345651.05, 268293.98, 346151.05, 268793.98);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Fed rate hike in 2026?', 'This market will resolve to “Yes” if the upper bound of the target federal funds rate is increased at any point between January 1, 2026 and the Fed''s December 2026 meeting, currently scheduled for December 8-9, 2026. Otherwise, this market will resolve to “No”. This market may not resolve to "No" until the Fed has released its rate change decision following its December meeting. The primary resolution source for this market will be the official website of the Federal Reserve (https://www.federa', 'general', 'active', 1988477.46, 1660105.03, 1988977.46, 1660605.03);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('US strike on Cuba by December 31?', 'This market will resolve to "Yes" if a US-initiated drone, missile, or air strike on the soil of Cuba is announced or credibly reported to have occurred by the listed date ET. Otherwise, this market will resolve to "No". For the purposes of this market, a qualifying "strike" is defined as the use of aerial bombs, drones, or missiles (including FPV and ATGM strikes as well as cruise or ballistic missiles) launched by any United States operatives, including military forces, intelligence agencies, ', 'politics', 'active', 495167.53, 2044153.13, 495667.53, 2044653.13);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Ledger IPO before 2027?', 'This market will resolve to "Yes" if the listed company completes an Initial Public Offering (IPO) by December 31, 2026, 11:59 PM ET, as confirmed by official company announcements or credible news sources. The IPO refers to the first sale of stock by the listed company to the public on any recognized stock exchange. If the listed company merges with another entity, is acquired, or ceases to exist before the market resolves, the market will also resolve to "No". This market will resolve early if', 'tech', 'active', 26934.33, 229583.11, 27434.33, 230083.11);
