INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will the upper bound of the target federal funds rate be ≥ 4.5% at the end of 2026?', 'The FED rate is defined in this market by the upper bound of the target federal funds range. The decisions on the target federal fund range are made by the Federal Open Market Committee (FOMC) meetings. This market will resolve according to the upper bound of the Federal Reserve’s target federal funds range after the December 2026 Federal Open Market Committee (FOMC) meeting, currently scheduled for December 8-9, 2026. This market may resolve immediately after the statement for the FOMC’s Decemb', 'politics', 'active', 81867.73, 1122069.47, 82367.73, 1122569.47);
